def smallest_change(arr):
    """Returns the minimum number of changes required to make an array palindromic."""
    if not arr:
        return 0
    i = 0
    j = len(arr) - 1
    changes = 0
    while i < j:
        if arr[i] != arr[j]:
            changes += 1
        i += 1
        j -= 1
    return changes

